function validate([low, high]) {
  if (!Number.isInteger(low) || !Number.isInteger(high)) return 'low and high are whole numbers.';
  if (low < 10) return 'low is at least 10.';
  if (high > 1000000000) return 'high is at most 10^9.';
  if (low > high) return 'low must not be greater than high.';
  return null;
}

