function sequentialDigits(low, high) {
  // Every sequential number is a contiguous piece of "123456789"; take them all, filter, then sort.
  const all = [];
  const digits = '123456789';
  for (let i = 0; i < digits.length; i++)
    for (let j = i + 1; j <= digits.length; j++) all.push(Number(digits.slice(i, j)));
  return all.filter(x => x >= low && x <= high).sort((a, b) => a - b);
}

