function generate(rand, size) {
  const LIMIT = 1000000000;
  const pickWithDigits = (d) => d >= 10 ? LIMIT : Math.pow(10, d - 1) + Math.floor(rand() * 9 * Math.pow(10, d - 1));
  const low = Math.max(10, pickWithDigits(2 + Math.floor(rand() * (size === 'large' ? 8 : 9))));
  const mode = rand();
  let high;
  if (mode < 0.25) high = low + Math.floor(rand() * 200);
  else if (mode < 0.5) high = low + Math.floor(rand() * low);
  else if (size === 'large' && mode < 0.8) high = LIMIT - Math.floor(rand() * 1000);
  else high = low + Math.floor(rand() * (LIMIT - low + 1));
  return [low, Math.min(LIMIT, high)];
}
